/* ---- blockquotes (long-form prose, the-name, getting-started) ---- */

article blockquote, main blockquote {
  border-left: 2px solid var(--accent-cyan);
  margin: var(--space-5) 0;
  padding: var(--space-1) var(--space-5);
  color: var(--ink-secondary);
  font-style: normal;        /* mono headings + sans body; no italics */
}
article blockquote p, main blockquote p {
  margin: 0 0 var(--space-3);
}
article blockquote p:last-child, main blockquote p:last-child {
  margin-bottom: 0;
}

/* ---- definition / metadata lists in prose ---- */

article dl, main dl {
  display: grid;
  grid-template-columns: minmax(8ch, max-content) 1fr;
  gap: var(--space-2) var(--space-4);
  margin: var(--space-4) 0;
  font-size: var(--text-sm);
}
article dt, main dt {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink-secondary);
  align-self: baseline;
}
article dd, main dd {
  margin: 0;
  color: var(--ink-primary);
}

/* ---- mobile polish ---- */

@media (max-width: 640px) {
  .hero { margin-top: var(--space-6); margin-bottom: var(--space-6); }
  .hero__title { letter-spacing: -0.03em; }
  .hero__cta { gap: var(--space-2); }
  .hero__btn { padding: var(--space-3) var(--space-4); }
  .bench-readout { padding: var(--space-4); }
  .bench-readout__value { font-size: 2rem; }
  .bench-comparison__stat-row { padding: var(--space-3); gap: var(--space-2); }
  .bench-comparison__stat { padding: var(--space-2) var(--space-2); }
  .bench-comparison__stat:nth-child(3) { border-left: none; }  /* row break in 2-col */
  .bench-comparison__block { padding: var(--space-4); }
  .bench-comparison__table th,
  .bench-comparison__table td,
  .br-body th,
  .br-body td {
    padding: 6px var(--space-2);
  }
  .br-body h2 { font-size: var(--text-xl); }
  .br-body h3 { font-size: var(--text-base); }
  .br-body > .meta { padding: var(--space-3); }
  .br-body .narrative {
    padding-left: var(--space-3);
    margin-bottom: var(--space-4);
  }
  .br-body .chart {
    padding: var(--space-3);
  }
  .br-body .chart svg,
  .br-body .chart img {
    min-width: 620px;
  }
  .br-body .machine dl {
    grid-template-columns: 1fr;
  }
}

/* ---- print hygiene ---- */

@media print {
  .hextra-nav-container, aside, .hextra-toc, footer { display: none; }
  .bench-readout, .bench-comparison, .feature, .br-body table {
    border: 1px solid #999 !important;
    background: white !important;
    color: black !important;
  }
}

